using System;using System.Data;using System.Linq;using System.Web.UI.WebControls;
namespace AQOONHUB_SMS.Modules.Reports{public partial class ExportHistory:ReportStage5Base{
 protected void Page_Load(object o,EventArgs e){if(!Require(ReportAuthorization.ExportHistory))return;if(!IsPostBack)Bind();}
 void Bind(){var d=Repo.GetExportHistory(CurrentUserId,CurrentRole);d.Columns.Add("CanRegenerate",typeof(bool));foreach(DataRow r in d.Rows){string k=Convert.ToString(r["ReportKey"]);r["CanRegenerate"]=ReportCatalog.Resolve(k)!=null||ValidSavedKey(k);}gv.DataSource=d;gv.DataBind();litTotal.Text=d.Rows.Count.ToString();litCsv.Text=d.Select("ExportFormat='CSV'").Length.ToString();litMeta.Text=d.Select("FileStatus='Metadata Only'").Length.ToString();litExpired.Text=d.Select("FileStatus='Expired'").Length.ToString();litToday.Text=d.AsEnumerable().Count(r=>r.Field<DateTime>("GeneratedAt").Date==DateTime.Today).ToString();}
 bool ValidSavedKey(string key){int id;if(!key.StartsWith("saved-",StringComparison.OrdinalIgnoreCase)||!int.TryParse(key.Substring(6),out id))return false;var r=Repo.GetSavedReport(id);if(r==null)return false;int owner=r["OwnerUserID"]==DBNull.Value?0:Convert.ToInt32(r["OwnerUserID"]);string vis=Convert.ToString(r["Visibility"]);return owner==CurrentUserId||ReportAuthorization.IsStage5Admin(CurrentRole)||vis=="Role-Based"||vis=="School-Wide";}
 protected void gv_RowCommand(object o,GridViewCommandEventArgs e){int id;if(!int.TryParse(Convert.ToString(e.CommandArgument),out id))return;if(e.CommandName=="DeleteMetadata"){if(Repo.DeleteExportMetadata(id,CurrentUserId,CurrentRole)){Audit("Export Metadata Deleted",null,"Export metadata",ReportAuthorization.ExportHistory);Msg("Export metadata deleted.",true);Bind();}return;}if(e.CommandName!="Regenerate")return;var ex=Repo.GetExportRecord(id,CurrentUserId,CurrentRole);if(ex==null){Msg("Export is unavailable or unauthorized.",false);return;}string key=Convert.ToString(ex["ReportKey"]);DataTable data;ReportDefinition def;if(key.StartsWith("saved-",StringComparison.OrdinalIgnoreCase)){int savedId;if(!int.TryParse(key.Substring(6),out savedId)||!ValidSavedKey(key)){Msg("Saved report configuration is unavailable.",false);return;}var sr=Repo.GetSavedReport(savedId);var v=ReportBuilderMetadata.Validate(Convert.ToString(sr["ConfigurationJson"]),CurrentRole);if(!v.Valid){Msg("Saved report configuration is invalid or no longer authorized.",false);return;}data=ReportBuilderMetadata.Execute(Repo,v,v.Source.ExportLimit);def=new ReportDefinition(key,Convert.ToString(sr["ReportName"]),v.Source.Category,v.Source.Handler,"Saved report",v.Config.orientation,new string[0],false,true);}else{def=ReportCatalog.Resolve(key);if(def==null||!ReportAuthorization.CanRunReport(CurrentRole,def)){Msg("Source report is unavailable or unauthorized.",false);return;}if(Convert.ToString(ex["FilterSummary"])!="All records"){Msg("Original structured filters are unavailable; regenerate from the source report.",false);return;}data=Repo.GetReportData(def.Handler,new ReportFilter(),ReportAuthorization.AllowSensitive(CurrentRole,def));}new ReportExportService(Repo).Export(Response,def,data,CurrentUserId,"Regenerated from authorized export metadata",Ip());}
 void Msg(string m,bool ok){litMessage.Text="<div role='alert' class='s5-msg "+(ok?"s5-ok":"s5-error")+"'>"+ReportUi.Enc(m)+"</div>";}
}}
